                    encryptionUtil.deterministicEncrypt(updateDto.getPhoneNumber()) : null;
            String encryptedZipCode = updateDto.getZipCode() != null ?
                    encryptionUtil.deterministicEncrypt(updateDto.getZipCode()) : null;
            String encryptedAddress = updateDto.getAddress() != null ?
                    encryptionUtil.deterministicEncrypt(updateDto.getAddress()) : null;

            // 상세주소: 양방향 암호화 (보안성 우선)
            String encryptedDetailedAddress = updateDto.getDetailedAddress() != null ?
                    encryptionUtil.encrypt(updateDto.getDetailedAddress()) : null;

            address.updateAddress(
                    encryptedRecipientName,
                    encryptedPhoneNumber,
                    encryptedZipCode,
                    encryptedAddress,
                    encryptedDetailedAddress,
                    updateDto.getIsDefault()
            );

            log.info("주소 수정 완료: 사용자={}, 주소ID={}", email, updateDto.getAddressId());
        } catch (AddressException e) {
            throw e; // 이미 AddressException이면 그대로 전파
        } catch (Exception e) {
            log.error("주소 수정 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, updateDto.getAddressId(), e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_UPDATE_ERROR, e);
        }
    }

    //주소지 삭제
    @Transactional
    public void deleteAddress(String email, Long addressId) {
        try {
            User user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            log.info("주소 삭제 시작: 사용자={}, 주소ID={}", email, addressId);

            Address address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new AddressNotFoundException(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));

            addressRepository.delete(address);
            log.info("주소 삭제 완료: 사용자={}, 주소ID={}", email, addressId);
        } catch (AddressException e) {
            throw e; // 이미 AddressException이면 그대로 전파
        } catch (Exception e) {
            log.error("주소 삭제 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_DELETE_ERROR, e);
        }
    }
}package com.fream.back.domain.address.service.query;

import com.fream.back.domain.address.dto.AddressResponseDto;
import com.fream.back.domain.address.entity.Address;
import com.fream.back.domain.address.exception.AddressErrorCode;
import com.fream.back.domain.address.exception.AddressException;
import com.fream.back.domain.address.exception.AddressNotFoundException;
import com.fream.back.domain.address.exception.AddressUserNotFoundException;
import com.fream.back.domain.address.repository.AddressRepository;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.repository.UserRepository;
import com.fream.back.global.utils.PersonalDataEncryptionUtil;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class AddressQueryService {

    private final UserRepository userRepository;
    private final AddressRepository addressRepository;
    private final PersonalDataEncryptionUtil encryptionUtil;

    //주소지 목록 조회
    @Transactional(readOnly = true)
    public List<AddressResponseDto> getAddresses(String email) {
        try {
            log.info("주소 목록 조회 시작: 사용자={}", email);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            List<AddressResponseDto> addresses = user.getAddresses().stream()
                    .map(address -> new AddressResponseDto(
                            address.getId(),
                            // 결정적 암호화된 필드들 복호화
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            // 상세주소는 양방향 암호화 복호화
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("주소 목록 조회 완료: 사용자={}, 조회된 주소 수={}", email, addresses.size());
            return addresses;
        } catch (AddressException e) {
            throw e; // 이미 AddressException이면 그대로 전파
        } catch (Exception e) {
            log.error("주소 목록 조회 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }

    //단일 주소지 조회
    @Transactional(readOnly = true)
    public AddressResponseDto getAddress(String email, Long addressId) {
        try {
            log.info("단일 주소 조회 시작: 사용자={}, 주소ID={}", email, addressId);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            Address address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new AddressNotFoundException(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));

            // 암호화 방식에 따라 적절한 복호화 적용
            AddressResponseDto responseDto = new AddressResponseDto(
                    address.getId(),
                    // 결정적 암호화된 필드들 복호화
                    encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                    encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                    encryptionUtil.deterministicDecrypt(address.getZipCode()),
                    encryptionUtil.deterministicDecrypt(address.getAddress()),
                    // 상세주소는 양방향 암호화 복호화
                    address.getDetailedAddress() != null ?
                            encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                    address.isDefault()
            );

            log.info("단일 주소 조회 완료: 사용자={}, 주소ID={}", email, addressId);
            return responseDto;
        } catch (AddressException e) {
            throw e; // 이미 AddressException이면 그대로 전파
        } catch (Exception e) {
            log.error("단일 주소 조회 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }

    /**
     * 수신자 이름으로 주소 검색 (결정적 암호화 활용)
     */
    @Transactional(readOnly = true)
    public List<AddressResponseDto> searchAddressesByRecipientName(String email, String recipientName) {
        try {
            log.info("이름으로 주소 검색 시작: 사용자={}, 검색어={}", email, recipientName);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            // 검색어를 암호화하여 DB와 비교
            String encryptedSearchTerm = encryptionUtil.encryptForSearch(recipientName);

            // Repository에서 암호화된 이름으로 검색하는 메서드 필요
            List<Address> foundAddresses = addressRepository.findByUserAndRecipientName(user, encryptedSearchTerm);

            List<AddressResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new AddressResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("이름으로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, recipientName, addresses.size());
            return addresses;
        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("이름으로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, recipientName, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }

    /**
     * 전화번호로 주소 검색 (결정적 암호화 활용)
     */
    @Transactional(readOnly = true)
    public List<AddressResponseDto> searchAddressesByPhoneNumber(String email, String phoneNumber) {
        try {
            log.info("전화번호로 주소 검색 시작: 사용자={}, 검색어={}", email, phoneNumber);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            // 검색어를 암호화하여 DB와 비교
            String encryptedSearchTerm = encryptionUtil.encryptForSearch(phoneNumber);

            // Repository에서 암호화된 전화번호로 검색하는 메서드 필요
            List<Address> foundAddresses = addressRepository.findByUserAndPhoneNumber(user, encryptedSearchTerm);

            List<AddressResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new AddressResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("전화번호로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, phoneNumber, addresses.size());
            return addresses;
        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("전화번호로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, phoneNumber, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }
}package com.fream.back.domain.address.repository;

import com.fream.back.domain.address.entity.Address;
import com.fream.back.domain.user.entity.User;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public interface AddressRepository extends JpaRepository<Address, Long> {

    /**
     * 특정 사용자의 모든 주소 조회
     */
    List<Address> findByUser(User user);

    /**
     * 특정 사용자의 특정 주소 조회
     */
    Optional<Address> findByIdAndUser(Long id, User user);

    /**
     * 특정 사용자의 기본 주소 조회
     */
    Optional<Address> findByUserAndIsDefaultTrue(User user);

    /**
     * 수신자 이름으로 주소 검색 (결정적 암호화 활용)
     * 암호화된 이름과 정확히 일치하는 주소들을 검색
     */
    @Query("SELECT a FROM Address a WHERE a.user = :user AND a.recipientName = :encryptedRecipientName")
    List<Address> findByUserAndRecipientName(@Param("user") User user,
                                             @Param("encryptedRecipientName") String encryptedRecipientName);

    /**
     * 전화번호로 주소 검색 (결정적 암호화 활용)
     * 암호화된 전화번호와 정확히 일치하는 주소들을 검색
     */
    @Query("SELECT a FROM Address a WHERE a.user = :user AND a.phoneNumber = :encryptedPhoneNumber")
    List<Address> findByUserAndPhoneNumber(@Param("user") User user,
                                           @Param("encryptedPhoneNumber") String encryptedPhoneNumber);

    /**
     * 주소로 검색 (결정적 암호화 활용)
     * 암호화된 주소와 정확히 일치하는 주소들을 검색
     */
    @Query("SELECT a FROM Address a WHERE a.user = :user AND a.address = :encryptedAddress")
    List<Address> findByUserAndAddress(@Param("user") User user,
                                       @Param("encryptedAddress") String encryptedAddress);

    /**
     * 우편번호로 주소 검색 (결정적 암호화 활용)
     * 암호화된 우편번호와 정확히 일치하는 주소들을 검색
     */
    @Query("SELECT a FROM Address a WHERE a.user = :user AND a.zipCode = :encryptedZipCode")
    List<Address> findByUserAndZipCode(@Param("user") User user,
                                       @Param("encryptedZipCode") String encryptedZipCode);

    /**
     * 복합 검색 - 여러 필드 조건으로 검색 (결정적 암호화 활용)
     * 모든 조건이 AND로 연결됨
     */
    @Query("SELECT a FROM Address a WHERE a.user = :user " +
            "AND (:encryptedRecipientName IS NULL OR a.recipientName = :encryptedRecipientName) " +
            "AND (:encryptedPhoneNumber IS NULL OR a.phoneNumber = :encryptedPhoneNumber) " +
            "AND (:encryptedAddress IS NULL OR a.address = :encryptedAddress) " +
            "AND (:encryptedZipCode IS NULL OR a.zipCode = :encryptedZipCode)")
    List<Address> findByUserAndMultipleFields(@Param("user") User user,
                                              @Param("encryptedRecipientName") String encryptedRecipientName,
                                              @Param("encryptedPhoneNumber") String encryptedPhoneNumber,
                                              @Param("encryptedAddress") String encryptedAddress,
                                              @Param("encryptedZipCode") String encryptedZipCode);

    /**
     * 특정 사용자의 주소 개수 조회
     */
    long countByUser(User user);

    /**
     * 특정 사용자의 기본 주소 여부 확인
     */
    boolean existsByUserAndIsDefaultTrue(User user);

    /**
     * 특정 사용자의 주소 중 기본 주소가 아닌 것들 조회
     */
    List<Address> findByUserAndIsDefaultFalse(User user);
}

